sys_script_include.script:
var MaxOfThreeSI = Class.create();
MaxOfThreeSI.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkUserCourse: function() {
        var checkUser = this.getParameter('sysparm_user');
        var checkCourse = this.getParameter('sysparm_course');
        var courseName = checkCourse.split(" (")[0];

        // gs.info('Usuário: ' + checkUser);
        // gs.info('Curso: ' + checkCourse);
        // gs.info('Nome extraído: ' + courseName);

        var arr = [];
		var count = 0;

        var grAjaxCheck = new GlideRecord('x_1488662_rsvp_t_0_course_enrollments');
        grAjaxCheck.addActiveQuery();
        grAjaxCheck.addQuery('opened_by', checkUser);
        grAjaxCheck.addEncodedQuery('course_daySTARTSWITH' + courseName);

        grAjaxCheck.query();

        while (grAjaxCheck.next()) {
            count++;
            arr.push(grAjaxCheck.getUniqueValue().toString());
        }

        // gs.info('Enrollments found: ' + arr.join('\n'));
        // gs.info(count);

        return arr.length >= 3 ? arr.join(',') : 'ok';
    },

    type: 'MaxOfThreeSI'
});
